srcDoc.css:
body {
  margin: 0;
  background: #eef1f5;
  color: #101828;
  font-family: Inter, Arial, sans-serif;
}

.page {
  padding: 18px;
  box-sizing: border-box;
}

.print-button {
  display: block;
  margin: 0 auto 14px;
  width: 240px;
  height: 42px;
  border: 0;
  border-radius: 7px;
  background: #101828;
  color: white;
  font-weight: 800;
  cursor: pointer;
}

.document {
  width: 210mm;
  min-height: 297mm;
  margin: 0 auto;
  background: white;
  box-sizing: border-box;
  padding: 18mm;
  box-shadow: 0 18px 50px rgba(15, 23, 42, 0.16);
}

.top-line {
  height: 7px;
  margin: -18mm -18mm 18mm;
  background: linear-gradient(90deg, #101828, #0f766e, #2563eb);
}

.header {
  display: flex;
  justify-content: space-between;
  gap: 28px;
  border-bottom: 1px solid #d0d5dd;
  padding-bottom: 18px;
}

.brand {
  display: flex;
  gap: 16px;
  align-items: flex-start;
}

.logo {
  width: 92px;
  max-height: 76px;
  object-fit: contain;
}

.logo-fallback {
  width: 84px;
  height: 68px;
  background: #101828;
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  font-weight: 900;
}

.company-name {
  font-size: 25px;
  line-height: 1.1;
  font-weight: 900;
}

.company-meta {
  margin-top: 8px;
  color: #667085;
  font-size: 12px;
  line-height: 1.45;
}

.doc-title {
  text-align: right;
  min-width: 250px;
}

.badge {
  display: inline-block;
  padding: 6px 10px;
  background: #ecfdf3;
  color: #047857;
  border: 1px solid #a7f3d0;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.doc-title h1 {
  margin: 10px 0 5px;
  font-size: 32px;
  letter-spacing: 0;
}

.doc-no {
  font-size: 18px;
  font-weight: 900;
}

.status {
  display: inline-block;
  margin-top: 8px;
  padding: 5px 9px;
  border: 1px solid #d0d5dd;
  font-size: 12px;
  font-weight: 800;
}

.info-strip {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
  margin: 18px 0;
}

.info-box {
  border: 1px solid #d0d5dd;
  padding: 11px;
}

.label {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  margin-bottom: 5px;
  font-weight: 700;
}

.value {
  font-size: 13px;
  font-weight: 800;
}

.summary-strip {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 9px;
  margin-bottom: 18px;
}

.summary-strip div {
  border: 1px solid #d0d5dd;
  border-left: 4px solid #0f766e;
  padding: 10px;
}

.summary-strip span {
  display: block;
  color: #667085;
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 800;
}

.summary-strip b {
  display: block;
  margin-top: 5px;
  font-size: 17px;
}

.items-wrap {
  border: 1px solid #d0d5dd;
}

.items-head {
  display: flex;
  justify-content: space-between;
  background: #101828;
  color: white;
  padding: 11px 12px;
}

.items-head h2 {
  margin: 0;
  font-size: 15px;
}

.items-head span {
  color: #d0d5dd;
  font-size: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  background: #f2f4f7;
  color: #344054;
  font-size: 11px;
  text-align: left;
  padding: 9px 8px;
  border-bottom: 1px solid #d0d5dd;
}

td {
  padding: 9px 8px;
  font-size: 12px;
  vertical-align: top;
  border-bottom: 1px solid #eaecf0;
}

tbody tr:nth-child(even) {
  background: #fbfcfd;
}

.product-code {
  font-weight: 900;
}

.product-name {
  margin-top: 2px;
  color: #667085;
  font-size: 11px;
}

.right {
  text-align: right;
  white-space: nowrap;
}

.qty.in {
  color: #047857;
  font-weight: 900;
}

.qty.out {
  color: #b42318;
  font-weight: 900;
}

.bottom-grid {
  display: grid;
  grid-template-columns: 1fr 150px;
  gap: 18px;
  margin-top: 18px;
  align-items: start;
}

.note-box {
  border: 1px solid #d0d5dd;
  min-height: 62px;
  padding: 11px;
  font-size: 12px;
  color: #475467;
  line-height: 1.45;
}

.barcode-box {
  margin-top: 12px;
  border: 1px solid #d0d5dd;
  padding: 10px;
  text-align: center;
}

.barcode-box svg {
  max-width: 100%;
}

.barcode-box div,
.qr-box div {
  margin-top: 4px;
  color: #667085;
  font-size: 9px;
  text-transform: uppercase;
  font-weight: 800;
}

.qr-box {
  border: 1px solid #d0d5dd;
  padding: 10px;
  text-align: center;
}

.qr-box img {
  width: 118px;
  height: 118px;
  image-rendering: pixelated;
}

.signatures {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 90px;
  margin-top: 56px;
}

.signature {
  border-top: 1px solid #101828;
  text-align: center;
  padding-top: 7px;
  font-size: 12px;
  font-weight: 700;
}

.footer {
  margin-top: 22px;
  padding-top: 10px;
  border-top: 1px solid #d0d5dd;
  color: #667085;
  font-size: 10px;
  text-align: center;
}

.empty {
  background: white;
  padding: 28px;
  text-align: center;
  color: #667085;
}

@media print {
  body {
    background: white;
  }
  .page {
    padding: 0;
  }
  .print-button {
    display: none;
  }
  .document {
    width: 210mm;
    min-height: 297mm;
    margin: 0;
    padding: 14mm;
    box-shadow: none;
  }
  .top-line {
    margin: -14mm -14mm 14mm;
  }
}

