import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function val(value) {
  return String(value ?? "");
}

function money(value) {
  return Number(value || 0).toFixed(2);
}

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function formatDate(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("en-GB");
}

function formatDateTime(value) {
  if (!value) return "";
  return new Date(value).toLocaleString("en-GB");
}

function pick(obj, keys, fallback = "") {
  for (const key of keys) {
    if (obj && obj[key] !== undefined && obj[key] !== null && obj[key] !== "") {
      return obj[key];
    }
  }

  return fallback;
}

function documentTitle(header) {
  const type = String(pick(header, ["documentType", "document_type", "type"], "")).toUpperCase();

  if (type === "STOCK_IN") return "Stock In";
  if (type === "STOCK_OUT") return "Stock Out";
  if (type === "STOCK_TRANSFER") return "Stock Transfer";
  if (type === "STOCK_ADJUSTMENT") return "Stock Adjustment";
  if (type === "OPENING_STOCK") return "Opening Stock";

  return "Stock Movement";
}

function movementPayload(header) {
  return [
    "STOCK_MOVEMENT",
    `DOCUMENT_ID=${pick(header, ["documentId", "id"], "")}`,
    `DOCUMENT_NO=${pick(header, ["documentNumber", "document_number"], "")}`,
    `TYPE=${pick(header, ["documentType", "document_type"], "")}`,
    `DATE=${pick(header, ["documentDate", "movementDate", "document_date"], "")}`,
    `WAREHOUSE=${pick(header, ["warehouseCode", "warehouse_code"], "")}`
  ].join("|");
}

function Barcode({ value }) {
  const ref = React.useRef(null);

  React.useEffect(() => {
    const clean = String(value || "").replace(/[^A-Za-z0-9-]/g, "");

    if (!clean || !ref.current) return;

    JsBarcode(ref.current, clean, {
      format: "CODE128",
      displayValue: true,
      fontSize: 12,
      height: 46,
      margin: 0
    });
  }, [value]);

  return <svg ref={ref}></svg>;
}

function App() {
  const model = appsmith.model || {};
  const header = model.header || {};
  const items = model.items || [];
  const username = model.username || appsmith.store?.username || "";

  const [qr, setQr] = React.useState("");

  const docNo = pick(header, [
    "documentNumber",
    "document_number",
    "stockDocumentNumber",
    "movementNumber",
    "number"
  ], "");

  const companyName = pick(header, ["companyName", "company_name"], "Company");
  const logo = pick(header, ["companyLogoPath", "company_logo_path", "logo_path"], "");

  React.useEffect(() => {
    async function buildQr() {
      if (!docNo) return;

      setQr(await QRCode.toDataURL(movementPayload(header), {
        margin: 1,
        width: 150,
        errorCorrectionLevel: "M"
      }));
    }

    buildQr();
  }, [docNo]);

  const totals = items.reduce(
    (sum, item) => {
      const quantity = Number(pick(item, ["quantity", "Quantity"], 0));
      const total = Number(pick(item, ["lineTotal", "totalCost", "stockValue", "Total"], 0));

      return {
        lines: sum.lines + 1,
        inQty: sum.inQty + (quantity > 0 ? quantity : 0),
        outQty: sum.outQty + (quantity < 0 ? Math.abs(quantity) : 0),
        netQty: sum.netQty + quantity,
        value: sum.value + total
      };
    },
    { lines: 0, inQty: 0, outQty: 0, netQty: 0, value: 0 }
  );

  if (!docNo && !items.length) {
    return <div className="empty">No stock movement data available.</div>;
  }

  return (
    <div className="page">
      <button className="print-button" onClick={() => window.print()}>
        Print Stock Movement
      </button>

      <div className="document">
        <div className="top-line" />

        <div className="header">
          <div className="brand">
            {logo ? (
              <img className="logo" src={logo} />
            ) : (
              <div className="logo-fallback">AX</div>
            )}

            <div>
              <div className="company-name">{companyName}</div>
              <div className="company-meta">
                <div>
                  {[pick(header, ["companyAddress", "company_address"], ""), pick(header, ["companyPostalCode", "company_postal_code"], ""), pick(header, ["companyCity", "company_city"], "")]
                    .filter(Boolean)
                    .join(", ")}
                </div>
                <div>Tax No: {pick(header, ["companyTaxNumber", "company_tax_number"], "-")}</div>
                <div>{[pick(header, ["companyEmail", "company_email"], ""), pick(header, ["companyPhone", "company_phone"], "")]
                  .filter(Boolean)
                  .join(" | ")}</div>
              </div>
            </div>
          </div>

          <div className="doc-title">
            <div className="badge">Inventory Document</div>
            <h1>{documentTitle(header)}</h1>
            <div className="doc-no">{docNo || "-"}</div>
            <div className="status">{pick(header, ["status", "Status"], "DRAFT")}</div>
          </div>
        </div>

        <div className="info-strip">
          <div className="info-box">
            <span className="label">Document Date</span>
            <span className="value">{formatDate(pick(header, ["documentDate", "movementDate", "document_date"], ""))}</span>
          </div>
          <div className="info-box">
            <span className="label">Created</span>
            <span className="value">{formatDateTime(pick(header, ["createdAt", "created_at"], ""))}</span>
          </div>
          <div className="info-box">
            <span className="label">Warehouse</span>
            <span className="value">
              {[pick(header, ["warehouseCode", "warehouse_code"], ""), pick(header, ["warehouseName", "warehouse_name"], "")]
                .filter(Boolean)
                .join(" - ") || "-"}
            </span>
          </div>
          <div className="info-box">
            <span className="label">Source</span>
            <span className="value">{pick(header, ["sourceDocumentNumber", "referenceNumber", "reference_number"], "-")}</span>
          </div>
        </div>

        <div className="summary-strip">
          <div>
            <span>Lines</span>
            <b>{totals.lines}</b>
          </div>
          <div>
            <span>In Qty</span>
            <b>{qty(totals.inQty)}</b>
          </div>
          <div>
            <span>Out Qty</span>
            <b>{qty(totals.outQty)}</b>
          </div>
          <div>
            <span>Net Qty</span>
            <b>{qty(totals.netQty)}</b>
          </div>
          <div>
            <span>Value</span>
            <b>{money(totals.value)}</b>
          </div>
        </div>

        <div className="items-wrap">
          <div className="items-head">
            <h2>Stock Movement Lines</h2>
            <span>{items.length} item{items.length === 1 ? "" : "s"}</span>
          </div>

          <table>
            <thead>
              <tr>
                <th>#</th>
                <th>Product</th>
                <th>Barcode</th>
                <th>Location</th>
                <th className="right">Qty</th>
                <th>Unit</th>
                <th className="right">Unit Cost</th>
                <th className="right">Total</th>
              </tr>
            </thead>
            <tbody>
              {items.map((item, index) => {
                const quantity = Number(pick(item, ["quantity", "Quantity"], 0));

                return (
                  <tr key={index}>
                    <td>{pick(item, ["lineNo", "LineNo"], index + 1)}</td>
                    <td>
                      <div className="product-code">{pick(item, ["productCode", "ProductCode", "Product Code"], "")}</div>
                      <div className="product-name">{pick(item, ["productName", "ProductName", "Product Name", "description"], "Item")}</div>
                    </td>
                    <td>{pick(item, ["barcode", "Barcode"], "-")}</td>
                    <td>{pick(item, ["locationCode", "Location", "warehouseLocation"], "-")}</td>
                    <td className={`right qty ${quantity < 0 ? "out" : "in"}`}>{qty(quantity)}</td>
                    <td>{pick(item, ["unitCode", "Unit", "unitName"], "")}</td>
                    <td className="right">{money(pick(item, ["unitCost", "unitPrice", "Unit Cost"], 0))}</td>
                    <td className="right">{money(pick(item, ["lineTotal", "totalCost", "stockValue", "Total"], 0))}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <div className="bottom-grid">
          <div>
            {(pick(header, ["note", "internalNote"], "") || "") && (
              <div className="note-box">
                <span className="label">Note</span>
                {pick(header, ["note", "internalNote"], "")}
              </div>
            )}

            <div className="barcode-box">
              <Barcode value={docNo} />
              <div>Stock document reference</div>
            </div>
          </div>

          <div className="qr-box">
            {qr && <img src={qr} />}
            <div>Inventory verification</div>
          </div>
        </div>

        <div className="signatures">
          <div className="signature">Prepared by</div>
          <div className="signature">Approved by</div>
        </div>

        <div className="footer">
          Printed: {formatDateTime(new Date())} {username ? `by ${username}` : ""}
        </div>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
